// Entrada: { post_id, solicitado_por }. Solo se acepta un UUID: el resto se lee de la base, nunca del cuerpo.
const body = ($json && typeof $json.body === 'object' && $json.body !== null) ? $json.body : $json;
const id = typeof body.post_id === 'string' ? body.post_id.trim() : '';
const ok = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id);
return [{ json: { valido: ok, ok: false, error: ok ? '' : 'post_id debe ser un UUID.', etapa: 'entrada', post_id: id, solicitado_por: typeof body.solicitado_por === 'string' ? body.solicitado_por.trim().slice(0, 120) : '' } }];

// Que le falta al articulo. Solo se completa lo que falta: el texto del editor no se toca nunca.
const entrada = $('Validar entrada').first().json;
const filas = $json.body;
const post = Array.isArray(filas) ? filas[0] : null;
if (!post) throw new Error('No existe el articulo ' + entrada.post_id + '.');
const trads = Array.isArray(post.posts_translations) ? post.posts_translations : [];
const locales = trads.map((t) => t.locale);
const original_locale = locales.includes(post.original_locale) ? post.original_locale : (locales[0] || 'es');
const origen = trads.find((t) => t.locale === original_locale) || trads[0];
if (!origen) throw new Error('El articulo no tiene ninguna version escrita.');
const opuesto = original_locale === 'es' ? 'en' : 'es';
const falta_portada = !post.cover_image_url;
const falta_categoria = post.category_id === null || post.category_id === undefined;
const falta_traduccion = !locales.includes(opuesto);
const texto = String(origen.content_html || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const slugArchivo = String(origen.slug || 'articulo').toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/-+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80).replace(/-+$/g, '') || 'articulo';
return [{ json: {
  post_id: post.id, status: post.status, titulo: origen.title, texto: texto.slice(0, 3000),
  original_locale, opuesto,
  origen: { title: origen.title, slug: origen.slug, content_html: origen.content_html, meta_title: origen.meta_title, meta_description: origen.meta_description },
  archivo_portada: slugArchivo + '-' + String(post.id).slice(0, 8) + '.webp',
  falta_portada, falta_categoria, falta_traduccion,
  solicitado_por: entrada.solicitado_por
} }];

const it = $input.first().json || {};
const raw = it.error ?? it.message ?? '';
let msg = typeof raw === 'string' ? raw : (raw && (raw.message || raw.description)) || '';
if (!msg && raw && typeof raw === 'object') { try { msg = JSON.stringify(raw).slice(0, 300); } catch (e) { msg = ''; } }
return [{ json: { ok: false, etapa: 'lectura', error: msg || 'No se pudo leer el articulo.' } }];

// Nunca falla: si GPT no responde, la portada sale con una escena neutra y la categoria queda sin asignar.
const DEFECTO = 'A single large smooth brushed-metal disc resting on coarse stone, with one hairline crack across its surface, no markings of any kind';
let data = null; let error = '';
try {
  let t = $json.output?.[0]?.content?.[0]?.text ?? $json.choices?.[0]?.message?.content ?? $json.message?.content ?? $json.text;
  if (typeof t === 'string') { t = t.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, ''); data = JSON.parse(t); }
  else if (t && typeof t === 'object') data = t;
} catch (e) { error = String(e.message || e).slice(0, 200); }
if (!data) error = error || String(($json.error && ($json.error.message || $json.error)) || 'sin respuesta').slice(0, 200);
const slugify = (s) => (s == null ? '' : String(s)).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const mapa = { criptomonedas: 1, forex: 2, 'materias-primas': 3, acciones: 4 };
const category_id = data ? (mapa[slugify(data.category)] || null) : null;
const p = data && typeof data.prompt_imagen === 'string' ? data.prompt_imagen.trim() : '';
return [{ json: { analisis_ok: !!data, error, category_id, prompt_imagen: p.length > 10 ? p.slice(0, 600) : DEFECTO } }];

// Decide qué hacer con la respuesta de Higgsfield: listo, seguir esperando o pasar al respaldo (OpenAI).
// El contador de intentos se guarda por solicitud (no por nodo) para que no se acumule entre las notas de una misma vuelta.
const j = $json;
const id = $('Higgsfield - Enviar').first().json.request_id || 'sin-id';
const sd = $getWorkflowStaticData('global');
sd.hf = sd.hf || {};
if (Object.keys(sd.hf).length > 50) sd.hf = {};
sd.hf[id] = (sd.hf[id] || 0) + 1;
const intentos = sd.hf[id];
const url = j.images && j.images[0] && j.images[0].url;
let decision = 'esperar';
if (j.status === 'completed' && url) decision = 'listo';
else if (['failed', 'nsfw', 'canceled', 'completed'].includes(j.status)) decision = 'fallo';
else if (intentos >= 14) decision = 'fallo'; // ~14 consultas x 12 s: unos 3 minutos
if (decision !== 'esperar') delete sd.hf[id];
return { json: { decision, status: j.status, url: decision === 'listo' ? url : null, intentos } };

