const d = $('Decidir').first().json;
const leer = (n) => { try { return $(n).first().json; } catch (e) { return null; } };
const fp = leer('Marcar fallo portada');
const ft = leer('Marcar fallo traduccion');
const hecho = {
  portada: d.falta_portada && !!leer('Guardar portada') && !fp,
  categoria: d.falta_categoria && !!leer('Guardar categoria') && !!(leer('Parsear clasificacion') || {}).category_id,
  traduccion: d.falta_traduccion && !!leer('Insertar traduccion') && !ft
};
const pendientes = [];
if (d.falta_portada && !hecho.portada) pendientes.push('portada');
if (d.falta_traduccion && !hecho.traduccion) pendientes.push('traduccion');
const errores = {};
if (fp && d.falta_portada) errores.portada = fp.error;
if (ft && d.falta_traduccion) errores.traduccion = ft.error;
return [{ json: { ok: pendientes.length === 0, post_id: d.post_id, titulo: d.titulo, hecho, pendientes, errores, solicitado_por: d.solicitado_por } }];

